        t.flaps = [_rt.get(data, '<f', 4 + i * 4) for i in range(4)]
        t.tvc = [_rt.get(data, '<f', 20 + i * 4) for i in range(2)]
        t.thrust = _rt.get(data, '<f', 28)
        if len(data) >= 36:
            t.roll_torque = _rt.get(data, '<f', 32)
        else:
            t.roll_torque = float('nan')
        return t


